// ---- Lifetime annotations ensure references are valid ----
// Syntax: 'a (pronounced "lifetime a")

// ---- Function with lifetime annotation ----
// This function returns a reference to the longer of two strings
fn longest<'a>(s1: &'a str, s2: &'a str) -> &'a str {
    if s1.len() > s2.len() {
        s1
    } else {
        s2
    }
}

// ---- Struct with lifetime annotation ----
struct ImportantExcerpt<'a> {
    part: &'a str,
}

// ---- Function with multiple lifetimes ----
fn longest_with_announcement<'a, 'b>(
    s1: &'a str,
    s2: &'a str,
    announcement: &'b str,
) -> &'a str {
    println!("Announcement: {}", announcement);
    if s1.len() > s2.len() {
        s1
    } else {
        s2
    }
}

fn main() {
    // ---- Using lifetime annotations ----
    let string1 = String::from("abcd");
    let string2 = "xyz";

    let result = longest(string1.as_str(), string2);
    println!("The longest string is: {}", result);

    // ---- Using struct with lifetime ----
    let novel = String::from("Call me Ishmael. Some years ago...");
    let first_sentence = novel.split('.').next().expect("Could not find a '.'");
    let excerpt = ImportantExcerpt {
        part: first_sentence,
    };
    println!("Excerpt: {}", excerpt.part);

    // ---- Lifetime elision (inferred) ----
    // Rust can often infer lifetimes
    // You don't need to annotate when Rust can figure it out

    // ---- Invalid lifetimes (won't compile) ----
    // let r;
    // {
    //     let x = 5;
    //     r = &x;  // ERROR! x doesn't live long enough
    // }
    // println!("r: {}", r);
}

// ---- Lifetime elision rules ----
// 1. Each parameter that is a reference gets its own lifetime parameter
// 2. If there is exactly one input lifetime, it is assigned to all output lifetimes
// 3. If there are multiple input lifetimes, but one is &self or &mut self, the lifetime of self is assigned to all output lifetimes

// ---- Examples of elision ----
fn first_word(s: &str) -> &str {
    // &str => &'a str implicitly
    let bytes = s.as_bytes();
    for (i, &item) in bytes.iter().enumerate() {
        if item == b' ' {
            return &s[0..i];
        }
    }
    &s[..]
}

